edits.before:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
}

edits.after:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
            {
                var step = -1;
                var date = self._d ? new Date(self._d.getTime()) : new Date();
                while(true){
                    date.setDate(date.getDate() + step);
                    if (self._o.minDate && date < self._o.minDate) {
                        date = new Date(self._o.minDate);
                        break;
                    }
                    if (self._o.maxDate && date > self._o.maxDate) {
                        date = new Date(self._o.maxDate);
                        break;
                    }
                    var disabled = false;
                    if (self._o.disableWeekends) {
                        var day = date.getDay();
                        if (day===0 || day===6) disabled = true;
                    }
                    if (!disabled && self._o.disableDayFn && self._o.disableDayFn(date)){
                        disabled = true;
                    }
                    if (!disabled) break;
                }
                self.setDate(date);
                break;
            }
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
            {
                var step = 1;
                var date = self._d ? new Date(self._d.getTime()) : new Date();
                while(true){
                    date.setDate(date.getDate() + step);
                    if (self._o.minDate && date < self._o.minDate) {
                        date = new Date(self._o.minDate);
                        break;
                    }
                    if (self._o.maxDate && date > self._o.maxDate) {
                        date = new Date(self._o.maxDate);
                        break;
                    }
                    var disabled = false;
                    if (self._o.disableWeekends) {
                        var day = date.getDay();
                        if (day===0 || day===6) disabled = true;
                    }
                    if (!disabled && self._o.disableDayFn && self._o.disableDayFn(date)){
                        disabled = true;
                    }
                    if (!disabled) break;
                }
                self.setDate(date);
                break;
            }
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
}
